preConditionHook:
// EMA TOUCH AFTER LONG ABSENCE (Brian's notes ON-85-a, #85): a touch of the
// long EMA whose gap since the previous touch is >= gapMultiple x the mean
// of the priorGaps gaps before it; long when the prior bar was wholly below
// the EMA, short when wholly above. The touch history is a bounded scan
// (EL has no registered arrays); the mean telescopes to
// (oldestTouch - newestTouch) / priorGaps.
// MultiWalk's WFSafe_Xaverage, ported unchanged from EmaGapBar (the EMA
// reference, with the measurements): price seed on the first calculated bar
// (ctx.CurrentBar() == 1), recurrence x + sf*(p - x) in ONE statement,
// sf = 2/(Length+1) from the raw input every bar, state carried on a length
// change (EL_XAverage_Lag_Probe.txt, 2026-09-17).
emaSf = 2.0 / (emaLength + 1.0);
if (ctx.CurrentBar() == 1) {
    emaVal = close[0];
} else {
    emaVal = emaVal + emaSf * (close[0] - emaVal);
}
// LAGGED EMA READS (MEASURED, XAVERAGE_LAG_FINDINGS.md): ema[k] is bit for
// bit the value k bars earlier and reads 0.0 before that history exists, so
// the zero-initialized ring buffer below is exact and the rule guards its
// first k bars on the bar counter instead of comparing against the zero.
// Re-seeded if the depth changes.
// Depth maxScanBars + 1 (at least 2, for the ema[1] read). The scan stops at
// CurrentBar - 1, so the zero pre-history is never compared against.
emaDepth = (int)maxScanBars + 1;
if (emaDepth < 2) {
    emaDepth = 2;
}
if (emaHistory.size() != (std::size_t)emaDepth) {
    emaHistory.assign((std::size_t)emaDepth, 0.0);
    emaCursor = 0;
}
emaHistory[emaCursor] = emaVal;
nTouch = 0;
newestTouch = 0;
oldestTouch = 0;
scanTo = (int)maxScanBars;
if (scanTo > ctx.CurrentBar() - 1) {
    scanTo = ctx.CurrentBar() - 1;
}
for (int ii = 1; ii <= scanTo; ++ii) {
    double lagged = emaHistory[(emaCursor + emaHistory.size() - (std::size_t)(ii)) % emaHistory.size()];
    if (el_le(low[ii], lagged) && el_ge(high[ii], lagged) && el_lt((double)nTouch, priorGaps + 1.0)) {
        nTouch = nTouch + 1;
        if (nTouch == 1) {
            newestTouch = ii;
        }
        oldestTouch = ii;
    }
}
prevEma = emaHistory[(emaCursor + emaHistory.size() - (std::size_t)(1)) % emaHistory.size()];
emaCursor = (emaCursor + 1) % emaHistory.size();
isTouch = el_le(low[0], emaVal) && el_ge(high[0], emaVal);
haveGaps = el_ge(priorGaps, 1.0) && el_ge((double)nTouch, priorGaps + 1.0);
meanGap = 0.0;
if (haveGaps) {
    meanGap = (double)(oldestTouch - newestTouch) / priorGaps;
}
